//! Compiled rows of the Product Operation Registry.
//!
//! One row per product operation reachable over a host boundary. Rows are
//! sorted by id and kept one per line so that a new command has exactly one
//! insertion point and a review diff shows exactly one row.
//! `#[rustfmt::skip]` keeps that layout; `operations_are_sorted_and_unique`
//! in `mod.rs` enforces the ordering.
//!
//! Columns: id, remote workspace stance, peer stance, CLI peer host support.
//! Desktop peer host support is derived (see `OperationDefinition::host_support`).
//!
//! Adding a Tauri command: register it in `src/apps/desktop/src/lib.rs`, then add
//! one `op(...)` row here with a real stance for every column. `Unaudited` is a
//! frozen backlog and may not be used for new rows (see `baseline.rs`).

use super::{
    HostSupport, OperationDefinition, OperationSurface, PeerStance, RemoteWorkspaceStance,
};
use PeerStance::{ControllerLocal, HostControlPlane, OperatorOnly, Proxied};
use RemoteWorkspaceStance::{Agnostic, LocalOnly, Routed, Unaudited, Unsupported};

const fn op(
    id: &'static str,
    remote_workspace: RemoteWorkspaceStance,
    peer: PeerStance,
    cli_peer: HostSupport,
) -> OperationDefinition {
    OperationDefinition {
        id,
        surface: OperationSurface::TauriCommand,
        remote_workspace,
        peer,
        cli_peer,
    }
}

/// A HostInvoke name that is not a registered Tauri command: CLI peer host
/// aliases kept for older controllers, and the detached-dispatch target verbs.
const fn host_invoke_only(
    id: &'static str,
    remote_workspace: RemoteWorkspaceStance,
    peer: PeerStance,
    cli_peer: HostSupport,
) -> OperationDefinition {
    OperationDefinition {
        id,
        surface: OperationSurface::HostInvokeOnly,
        remote_workspace,
        peer,
        cli_peer,
    }
}

const HANDLED: HostSupport = HostSupport::Handled;
/// Cell used by every `ControllerLocal` / `OperatorOnly` row: the verdict refuses
/// the command before host dispatch, so per-host support is not consulted.
pub(super) const REFUSED: HostSupport = HostSupport::Unsupported {
    reason: "the controller keeps this command; peer hosts refuse it before dispatch",
};
pub(super) const CLI_NOT_IMPLEMENTED: HostSupport = HostSupport::Unsupported {
    reason: "the CLI peer host has no handler for this command",
};
pub(super) const CLI_NO_DESKTOP_IDE_SURFACE: HostSupport = HostSupport::Unsupported {
    reason: "the CLI peer host does not run this desktop IDE surface",
};
pub(super) const CLI_NO_BROWSER_OR_OS_AUTOMATION: HostSupport = HostSupport::Unsupported {
    reason: "the CLI peer host has no browser or OS automation runtime",
};
pub(super) const CLI_NO_REMOTE_WORKSPACE_UI: HostSupport = HostSupport::Unsupported {
    reason: "the CLI peer host does not expose the remote-workspace UI surface",
};
pub(super) const SOFT_EMPTY_NO_CRON_HOST: HostSupport = HostSupport::SoftEmpty {
    reason: "the CLI peer host has no cron host; readiness is acknowledged so hydrate succeeds",
};
pub(super) const SOFT_EMPTY_MINIAPPS: HostSupport = HostSupport::SoftEmpty {
    reason: "MiniApps are a desktop-hosted runtime; the CLI peer host reports an empty catalog so hydrate succeeds",
};
pub(super) const SOFT_EMPTY_ACP_CLIENTS: HostSupport = HostSupport::SoftEmpty {
    reason: "ACP client management is a desktop settings surface; the CLI peer host reports none",
};
pub(super) const SOFT_EMPTY_BACKGROUND_COMMANDS: HostSupport = HostSupport::SoftEmpty {
    reason: "background command activities are desktop-hosted; the CLI peer host reports none",
};

